#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
int main(int argc, char **argv) {
    (void)argc;
    if (setenv("LEAN_NUM_THREADS", "8", 1) != 0) { perror("setenv"); return 127; }
    execv("/opt/lean-audit/lean-4.34.0-rc2-linux/bin/lake", argv);
    perror("execv pinned lake");
    return 127;
}
